#!/usr/bin/env python3
"""Read-only dashboard for the Stage-5 cross-object token-overlap audit."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


ROOT = Path(
    "/data/gaoya/agent-data/outputs/object_query_information_flow_redesign/"
    "latest3350_v1/stage5_token_overlap_audit"
)
CATALOG = ROOT / "catalog.json"


def catalog() -> dict[str, Any]:
    try:
        payload = json.loads(CATALOG.read_text(encoding="utf-8"))
    except (OSError, ValueError, json.JSONDecodeError):
        return {"schema_version": 1, "units": [], "error": "catalog is not ready"}
    return payload if isinstance(payload, dict) else {"schema_version": 1, "units": []}


def asset(case: str, seed: int, kind: str) -> Path | None:
    if kind not in {"baseline", "overlay"}:
        return None
    for unit in catalog().get("units", []):
        if str(unit.get("case")) != case or int(unit.get("seed", -1)) != seed:
            continue
        key = "baseline_video" if kind == "baseline" else "overlay_video"
        candidate = Path(str(unit.get(key, "")))
        return candidate if candidate.is_file() else None
    return None


def page() -> str:
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stage 5 · Latent Token 重叠审计</title><style>
:root{--night:#071018;--panel:#101d29;--panel2:#152635;--mist:#e7f0f7;--muted:#91a7b8;--line:#294152;--cyan:#00d4ff;--amber:#ffbd38;--violet:#cf69ff;--green:#5bd68b;--danger:#ff374f;--danger2:#7b1321}*{box-sizing:border-box}html{background:var(--night);color:var(--mist);font-family:"IBM Plex Sans","Noto Sans SC",system-ui,sans-serif}body{margin:0;background:linear-gradient(135deg,#071018 0,#0a1620 48%,#08131b 100%);min-height:100vh}a{color:var(--cyan)}header{padding:22px clamp(16px,3vw,44px) 18px;border-bottom:1px solid var(--line);background:#071018ed;position:sticky;top:0;z-index:8;backdrop-filter:blur(12px)}.crumb{font:12px ui-monospace,SFMono-Regular,monospace;color:var(--muted)}.title-line{display:flex;align-items:end;justify-content:space-between;gap:24px;flex-wrap:wrap;margin-top:13px}h1{margin:0;font-size:clamp(30px,4.5vw,64px);letter-spacing:-.045em;line-height:.96;max-width:890px}h1 em{font-style:normal;color:var(--danger)}.lead{max-width:850px;color:#bfd0dc;line-height:1.65;margin:14px 0 0}.controls{display:flex;gap:9px;align-items:end;flex-wrap:wrap}.controls label{font:11px ui-monospace,monospace;color:var(--muted);display:grid;gap:5px}.controls select,.controls button{height:38px;border:1px solid var(--line);border-radius:5px;background:var(--panel2);color:var(--mist);padding:0 11px;font-weight:700}.controls button{cursor:pointer}.controls button:focus-visible,.controls select:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}main{width:min(1900px,calc(100% - 24px));margin:auto;padding:18px 0 72px}.summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--line);background:var(--panel);margin-bottom:16px}.stat{padding:15px 17px;border-right:1px solid var(--line)}.stat:last-child{border:0}.stat b{display:block;font:700 25px ui-monospace,monospace}.stat span{color:var(--muted);font-size:11px}.warning{border:1px solid #8f2435;background:linear-gradient(90deg,#36111a,#171822);padding:13px 16px;margin-bottom:16px;display:flex;gap:13px;align-items:center}.warning i{width:12px;height:12px;background:var(--danger);box-shadow:0 0 18px var(--danger);transform:rotate(45deg);flex:none}.warning p{margin:0;line-height:1.55;font-size:13px}.unit-head{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px;align-items:end;margin:20px 0 10px}.unit-head h2{font-size:clamp(19px,2.5vw,31px);margin:0;overflow-wrap:anywhere}.unit-head code{font-size:12px;color:var(--muted)}.badges{display:flex;gap:7px;flex-wrap:wrap;justify-content:end}.badge{font:11px ui-monospace,monospace;border:1px solid var(--line);padding:6px 9px;background:var(--panel)}.badge.danger{border-color:#a5293c;color:#ff8797}.videos{display:grid;grid-template-columns:1fr 1fr;gap:12px}.video-card{border:1px solid var(--line);background:var(--panel);overflow:hidden}.video-card h3{font:12px ui-monospace,monospace;letter-spacing:.05em;margin:0;padding:10px 12px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between}.video-card video{display:block;width:100%;aspect-ratio:1280/704;background:#020608}.video-card.overlay{border-color:#7d2635}.video-card.overlay h3{background:#35121b;color:#ff9ca9}.timeline-wrap{margin-top:12px;border:1px solid var(--line);background:var(--panel);padding:12px}.timeline-head{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:9px}.timeline-head h3{margin:0;font-size:14px}.timeline{display:grid;grid-template-columns:repeat(13,minmax(42px,1fr));gap:5px}.latent{border:1px solid var(--line);background:#102230;color:var(--mist);padding:7px 3px;min-height:54px;cursor:pointer;font:10px ui-monospace,monospace}.latent b{display:block;font-size:14px}.latent.hit{border-color:var(--danger);background:linear-gradient(#521623,#26131a);color:#ffd5db}.latent:hover{transform:translateY(-1px)}.detail-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(330px,.65fr);gap:12px;margin-top:12px}.events,.definition{border:1px solid var(--line);background:var(--panel);padding:14px;overflow:auto}.events h3,.definition h3{margin:0 0 10px;font-size:15px}table{border-collapse:collapse;width:100%;font:11px ui-monospace,monospace;min-width:720px}th,td{padding:8px;border-bottom:1px solid var(--line);text-align:left}th{color:var(--muted);font-weight:500}.token{color:#ff91a0;font-weight:800}.objects{display:flex;gap:5px;flex-wrap:wrap}.object{padding:2px 5px;border:1px solid currentColor}.formula{padding:10px;background:#08131b;border-left:3px solid var(--danger);font:12px/1.6 ui-monospace,monospace;overflow-wrap:anywhere}.definition p,.definition li{color:#b7c8d4;font-size:13px;line-height:1.6}.definition ul{padding-left:20px}.legend{display:flex;flex-wrap:wrap;gap:8px}.legend span{font:11px ui-monospace,monospace;display:flex;gap:5px;align-items:center}.legend i{width:12px;height:12px;border:2px solid currentColor}.footer{color:var(--muted);font:11px ui-monospace,monospace;margin-top:16px}@media(max-width:980px){header{position:static}.summary{grid-template-columns:1fr 1fr}.stat:nth-child(2){border-right:0}.stat:nth-child(-n+2){border-bottom:1px solid var(--line)}.videos,.detail-grid{grid-template-columns:1fr}.timeline{grid-template-columns:repeat(7,1fr)}.unit-head{grid-template-columns:1fr}.badges{justify-content:start}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}.latent:hover{transform:none}}
</style></head><body><header><a class="crumb" href="/">← 返回 8092 总入口</a><div class="title-line"><div><h1>同一个格子，<br><em>两个对象。</em></h1><p class="lead">把冻结 CoTracker 点量化到 Wan 的 13×22×40 latent-video token 网格。彩色框是各对象 token；红色填充、白色叉号是两个或更多对象共享的 token。原视频与 overlay 使用同一 seed、同一 Baseline。</p></div><div class="controls"><label>CASE / SEED<select id="unit"></select></label><button id="replay">同步重播</button><button id="pause">全部暂停</button></div></div></header><main><div id="summary" class="summary"></div><div class="warning"><i></i><p>共享 token 说明当前 attention 分辨率无法区分对应对象。它不是跟踪点坐标相同，而是多个点经过 32×32 pixel cell 量化后落入同一 latent cell；因此不能未经额外规则就把该 token 唯一分配给某个 <code>R_i</code>。</p></div><div id="content"></div><div class="footer">RGB frame → 最近 latent anchor；F00/F04/…/F48 为精确锚点。视频只加载当前选中的 case-seed。</div></main><script>
const api='/api/object-query-stage5-token-overlap',q=new URL(location.href).searchParams,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let data,unit;
const media=(kind,u)=>`${api}/asset?${new URLSearchParams({kind,case:u.case,seed:String(u.seed)})}`;
function objectTag(name,u){const rgb=u.object_colors_rgb[name]||[220,220,220],color=`rgb(${rgb.join(',')})`;return `<span class="object" style="color:${color}">${esc(name)}</span>`}
function renderSummary(){const uniqueCases=new Set(data.units.map(x=>x.case)).size;$('summary').innerHTML=[['8 / 30',`重叠 case-seed（实时 ${data.overlap_case_seed_units}/30）`],[String(uniqueCases),'受影响 case'],[String(data.overlap_events),'共享 token-time 事件'],['22 × 40','每个 latent 时刻的空间网格']].map(x=>`<div class="stat"><b>${esc(x[0])}</b><span>${esc(x[1])}</span></div>`).join('')}
function render(){unit=data.units[Number($('unit').value)||0];q.set('case',unit.case);q.set('seed',unit.seed);history.replaceState(null,'',`${location.pathname}?${q}`);const fps=unit.video.fps||30;const events=unit.events.map(e=>`<tr><td>R${String(e.latent_t).padStart(2,'0')}</td><td>F${String(e.anchor_frame).padStart(2,'0')}</td><td>${e.grid_y}, ${e.grid_x}</td><td>${e.spatial_token}</td><td class="token">${e.global_token}</td><td><div class="objects">${e.objects.map(n=>objectTag(n,unit)).join('')}</div></td></tr>`).join('');const timeline=unit.counts_by_latent.map((n,t)=>`<button class="latent ${n?'hit':''}" data-t="${t}"><span>R${String(t).padStart(2,'0')}</span><b>${n||'·'}</b><span>F${String(unit.anchor_frames[t]).padStart(2,'0')}</span></button>`).join('');const legend=unit.objects.map(n=>objectTag(n,unit)).join('');$('content').innerHTML=`<div class="unit-head"><div><h2>${esc(unit.case)}</h2><code>seed ${unit.seed} · ${esc(unit.tracks_npz)}</code></div><div class="badges"><span class="badge danger">${unit.overlap_event_count} overlap events</span><span class="badge danger">${unit.overlap_latent_count}/13 latent anchors affected</span><span class="badge">${esc(Object.entries(unit.pair_counts).map(([k,v])=>`${k}: ${v}`).join(' · '))}</span></div></div><div class="videos"><article class="video-card"><h3><span>BASELINE</span><span>no overlay</span></h3><video id="baseline" controls muted loop playsinline preload="metadata" src="${media('baseline',unit)}"></video></article><article class="video-card overlay"><h3><span>LATENT TOKEN OVERLAY</span><span>red = shared cell</span></h3><video id="overlay" controls muted loop playsinline preload="metadata" src="${media('overlay',unit)}"></video></article></div><section class="timeline-wrap"><div class="timeline-head"><h3>13 latent anchors · 点击跳转</h3><div class="legend">${legend}<span style="color:var(--danger)"><i></i>overlap</span></div></div><div class="timeline">${timeline}</div></section><div class="detail-grid"><section class="events"><h3>精确重叠 token</h3><table><thead><tr><th>latent</th><th>anchor</th><th>grid y,x</th><th>spatial id</th><th>global token id</th><th>objects</th></tr></thead><tbody>${events}</tbody></table></section><aside class="definition"><h3>怎么读</h3><div class="formula">global_token = t × (22×40) + y × 40 + x</div><ul><li><b>彩色空心框</b>：该对象在当前 latent anchor 的稀疏 token。</li><li><b>红色框 + 白色 X</b>：至少两个对象量化到同一个 token。</li><li>每格精确对应输出图像中的 <b>32×32 pixels</b>。</li><li>非锚点 RGB 帧显示最近的 frozen latent anchor；左上角标明映射。</li></ul><p>这些红格就是 Stage 5 原块对角定义无法唯一分配的 token。若采用 <code>R_amb</code>，它们将从所有对象集合和背景集合中单独留出，相关边不消融。</p></aside></div>`;document.querySelectorAll('.latent').forEach(b=>b.onclick=()=>{const t=Number(b.dataset.t),sec=unit.anchor_frames[t]/fps;videos().forEach(v=>v.currentTime=sec)})}
function videos(){return ['baseline','overlay'].map($).filter(Boolean)}function replay(){const vs=videos();vs.forEach(v=>{v.currentTime=0});Promise.allSettled(vs.map(v=>v.play()))}function pause(){videos().forEach(v=>v.pause())}
async function load(){data=await fetch(`${api}/catalog`,{cache:'no-store'}).then(r=>r.json());renderSummary();const requestedCase=q.get('case'),requestedSeed=Number(q.get('seed'));$('unit').innerHTML=data.units.map((u,i)=>`<option value="${i}">${esc(u.case)} · seed ${u.seed} · ${u.overlap_event_count} overlaps</option>`).join('');const selected=data.units.findIndex(u=>u.case===requestedCase&&u.seed===requestedSeed);$('unit').value=String(selected>=0?selected:0);render()}
$('unit').addEventListener('change',render);$('replay').addEventListener('click',replay);$('pause').addEventListener('click',pause);load();
</script></body></html>'''

